const fresh=()=>({id:'CE-'+crypto.getRandomValues(new Uint32Array(1))[0].toString(36).toUpperCase(),index:0,xp:0,states:{},errors:0,attempts:0,history:[]});
let s;try{s=JSON.parse(localStorage.getItem(KEY))||fresh()}catch(e){s=fresh()}function save(){try{localStorage.setItem(KEY,JSON.stringify(s))}catch(e){$('dialog').dataset.storage='unavailable'}}
function rec(){const m=MISSIONS[s.index];if(!m)return null;return s.states[m.id]||(s.states[m.id]={status:'new',tries:0,errors:0,values:[]})}
const norm=x=>x.toLowerCase().normalize('NFKC').replace(/[’‘]/g,"'").replace(/[.!?;,:]/g,'').trim().replace(/\s+/g,' ');
