function esc(x){return String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const enc=new TextEncoder(),dec=new TextDecoder();function b64(a){return btoa(String.fromCharCode(...new Uint8Array(a))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')}function un64(a){return Uint8Array.from(atob(a.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0))}function pack(o){return b64(enc.encode(JSON.stringify(o)))}
function request(){let r=rec();if(!r.nonce)r.nonce=crypto.getRandomValues(new Uint32Array(2)).join('-');save();return pack({student:s.id,mission:MISSIONS[s.index].id,nonce:r.nonce})}
async function applyCode(code){try{let [payload,sig]=code.trim().split('.');const key=await crypto.subtle.importKey('jwk',PUBLIC_KEY,{name:'ECDSA',namedCurve:'P-256'},false,['verify']);if(!await crypto.subtle.verify({name:'ECDSA',hash:'SHA-256'},key,un64(sig),enc.encode(payload)))throw Error('Firma incorrecta');const v=JSON.parse(dec.decode(un64(payload))),r=rec(),m=MISSIONS[s.index];if(!r||!['pending','rejected'].includes(r.status)||v.student!==s.id||v.mission!==m.id||v.nonce!==r.nonce)throw Error('Código no corresponde a esta entrega');if(v.decision==='approved'&&Number.isFinite(v.grade)&&v.grade>=v.threshold&&v.grade<=10){r.status='approved';r.grade=v.grade;r.comment=v.comment;s.history.push({mission:m.id,grade:v.grade,decision:v.decision,date:new Date().toISOString()});s.index++;save();render();showHome();return 'Validación correcta.'}if(v.decision==='rejected'){r.status='rejected';r.comment=v.comment;r.grade=v.grade;delete r.nonce;s.history.push({mission:m.id,grade:v.grade,decision:v.decision,date:new Date().toISOString()});save();render();showPaper();return 'Revisar ejercicio y generar nueva solicitud.'}throw Error('Calificación o decisión inválida')}catch(e){return 'No se ha aplicado: '+e.message}}
let p={x:475,y:345,dir:0,z:'city'},keys=new Set(),started=false,step=0,cam={x:0,y:0};const dialog=$('dialog');
function render(){const done=s.index,digital=Object.values(s.states).filter(r=>['pending','rejected','approved'].includes(r.status)).length;$('sid').textContent=s.id;$('xp').textContent=s.xp;$('progressText').textContent=`Digital ${digital}/10 · Validado ${done}/10`;$('bar').style.width=done*10+'%';$('missionList').innerHTML=MISSIONS.map((m,i)=>`<div class="mission ${i===done?'active':''} ${i<done?'done':''}"><span>${m.id}</span>${esc(m.title)}<span>${i<done?'APTO':i===done?'ACTIVA':'BLOQ.'}</span></div>`).join('');$('zone').textContent=p.z.toUpperCase()}
function showHome(){if(s.index===10){dialog.innerHTML='<div class="eyebrow">MISSION COMPLETE</div><h2>IDENTITY PROTOCOL / VALIDADO</h2><p>Has superado las diez submisiones. Misión 02 aún no implementada en esta demo.</p>';return}const m=MISSIONS[s.index],r=rec();if(['pending','rejected'].includes(r.status)){showPaper();return}dialog.innerHTML=`<div class="eyebrow">OBJECTIVE ${m.id} / ${esc(m.location)}</div><h2>${esc(m.title)}</h2><p>${esc(m.story)}</p><p class="muted">Ve al marcador amarillo y pulsa E. Contacto: ${esc(m.npc)} · ${esc(m.grammar)}</p>`}
function showChallenge(){const m=MISSIONS[s.index],r=rec();if(!m)return;if(['pending','rejected'].includes(r.status)){showPaper();return}r.status='in_progress';save();keys.clear();dialog.innerHTML=`<div class="eyebrow">TERMINAL ${m.id} · ${esc(m.npc)}</div><h2>${esc(m.title)}</h2><div class="reading">${esc(m.reading)}</div><p>Escribe respuestas completas en inglés. No se distingue entre mayúsculas y minúsculas; se admiten las variantes previstas.</p><form id="challenge"><div class="questions">${m.questions.map((q,i)=>`<div class="q"><label for="q${i}">${i+1}. ${esc(q.prompt)}</label><input id="q${i}" required autocomplete="off" value="${esc(r.values[i]||'')}"><small></small></div>`).join('')}</div><div class="actions"><button class="primary" type="submit">Comprobar respuestas</button><button type="button" id="back">Volver al mapa</button></div></form><div id="feedback" role="status"></div>`;$('back').onclick=showHome;$('challenge').onsubmit=e=>{e.preventDefault();let wrong=0;r.tries++;s.attempts++;m.questions.forEach((q,i)=>{const a=$('q'+i),good=isCorrect(a.value,q.answers);r.values[i]=a.value;const box=a.parentElement;box.className='q '+(good?'correct':'wrong');box.querySelector('small').textContent=good?'Correcto.':'Revisa concordancia, pronombre, orden y vocabulario. Ejemplo válido: '+q.answers[0];if(!good)wrong++});r.errors+=wrong;s.errors+=wrong;if(wrong===0){r.status='pending';s.xp+=m.xp;save();render();showPaper()}else{$('feedback').textContent=`${wrong} respuestas pendientes. Corrígelas y vuelve a comprobar.`;save()}};dialog.scrollIntoView({block:'nearest',behavior:'smooth'})}
function showPaper(){const m=MISSIONS[s.index],r=rec();if(!m)return;const req=request();dialog.innerHTML=`<div class="paper"><div class="eyebrow no-print">${r.status==='rejected'?'REVISIÓN REQUERIDA':'DIGITAL COMPLETED'} / +${m.xp} XP</div><h2>Ficha manuscrita ${m.id} — ${esc(m.title)}</h2><p><strong>ID alumno:</strong> ${esc(s.id)} · <strong>Gramática:</strong> ${esc(m.grammar)}</p><p><strong>Objetivo:</strong> aplicar los contenidos de la misión con producción escrita individual.</p><div class="reading">${esc(m.reading)}</div><h3>Actividad obligatoria</h3><p>${esc(m.paper)}</p><p><strong>Extensión mínima:</strong> ${esc(m.minimum)}</p><p><strong>Entrega:</strong> manuscrita en papel, con ID, fecha y número de submisión. Muestra tu trabajo al profesor.</p><p><strong>Criterios:</strong> gramática 35%, comprensión 25%, vocabulario 20%, instrucciones 15%, presentación 5%. Nota mínima inicial: 7/10, ajustable por el docente.</p><div class="notice">${r.status==='rejected'?'No apto. Observación: '+esc(r.comment||'Revisa el ejercicio.'):'Siguiente submisión bloqueada hasta validación docente.'}</div><div class="actions"><button onclick="print()">Imprimir ficha</button></div><div class="no-print"><label>Solicitud para el profesor (cópiala o muéstrala)</label><textarea id="request" rows="3" readonly>${req}</textarea><div class="actions"><button id="copyReq">Copiar solicitud</button></div><label for="approval">Código firmado de validación</label><textarea id="approval" rows="3" placeholder="Pega aquí el código facilitado por el profesor"></textarea><div class="actions"><button id="validate" class="primary">Validar código</button></div><div id="validationMsg" role="status"></div></div></div>`;$('copyReq').onclick=()=>{$('request').select();try{document.execCommand('copy')}catch(e){}};$('validate').onclick=async()=>{const v=$('approval').value;const msg=await applyCode(v);const el=$('validationMsg');if(el)el.textContent=msg};}
function enter(z){p.z=z;p.x=320;p.y=290;render()}
function interact(){if(!started)return;let a=route[s.index];if(a&&p.z===a.z&&Math.hypot(p.x-a.x,p.y-a.y)<38){showChallenge();return}if(p.z!=='city'&&Math.hypot(p.x-320,p.y-330)<44){const old=p.z;p.z='city';p.x=old==='lab'?678:103;p.y=old==='lab'?230:400;render();return}if(p.z==='city'){let door=doors.find(d=>Math.hypot(p.x-d.x,p.y-d.y)<34);if(door){enter(door.z);return}let n=NPCS.find(n=>Math.hypot(p.x-n.x,p.y-n.y)<32);if(n){dialog.innerHTML=`<div class="eyebrow">NPC / ${esc(n.name)}</div><h2>${esc(n.name)}</h2><p>“Check the active objective. The city is not safe.”</p><button onclick="showHome()">Cerrar diálogo</button>`;return}}}
function blocked(x,y){const w=p.z==='city'?960:640,h=p.z==='city'?640:360;if(x<13||x>w-13||y<40&&p.z!=='city'||y<13||y>h-15)return true;return(p.z==='city'?buildings:roomBlocks).some(([a,b,c,d])=>x>a-6&&x<a+c+6&&y>b-4&&y<b+d+4)}
window.addEventListener('keydown',e=>{if(/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName))return;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','w','a','s','d','W','A','S','D','e','E'].includes(e.key)){e.preventDefault();if(e.key.toLowerCase()==='e'&&!e.repeat)interact();else keys.add(e.key.toLowerCase())}});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>keys.clear());document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.key.toLowerCase())};b.onpointerup=b.onpointercancel=()=>keys.delete(b.dataset.key.toLowerCase())});
const rain=Array.from({length:110},(_,i)=>({x:(i*83)%640,y:(i*47)%360,v:50+i%100}));let last=0;
function frame(t){let dt=Math.min(.05,(t-last)/1000||0);last=t;let dx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),dy=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);if(started&&(dx||dy)){const speed=112*dt/Math.hypot(dx,dy);if(!blocked(p.x+dx*speed,p.y))p.x+=dx*speed;if(!blocked(p.x,p.y+dy*speed))p.y+=dy*speed;p.dir=dx?dx<0?2:3:dy<0?1:0;step+=dt*8}else step=0;cam.x=p.z==='city'?Math.max(0,Math.min(320,p.x-320)):0;cam.y=p.z==='city'?Math.max(0,Math.min(280,p.y-180)):0;ctx.fillStyle='#101a26';ctx.fillRect(0,0,640,360);const bg=imgs[p.z];if(bg.complete&&bg.naturalWidth)ctx.drawImage(bg,-Math.round(cam.x),-Math.round(cam.y));const sprite=(x,y,row,f,npc=false)=>{if(!imgs.player.complete||!imgs.player.naturalWidth)return;ctx.save();if(npc)ctx.filter='hue-rotate(95deg)';ctx.drawImage(imgs.player,f*20,row*28,20,28,Math.round(x-cam.x-10),Math.round(y-cam.y-25),20,28);ctx.restore()};if(p.z==='city')NPCS.forEach((n,i)=>sprite(n.x,n.y,0,(Math.floor(t/700)+i)%4,true));const a=route[s.index];function marker(x,y,color,label){x-=cam.x;y-=cam.y;ctx.strokeStyle=color;ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(x,y,13+Math.sin(t/200)*2,6,0,0,Math.PI*2);ctx.stroke();ctx.fillStyle=color;ctx.font='10px monospace';ctx.textAlign='center';ctx.fillText(label,x,y-31)}if(a&&a.z===p.z)marker(a.x,a.y,'#ffdb85',MISSIONS[s.index].id+' / E');if(p.z==='city')doors.forEach(d=>marker(d.x,d.y,'#77c0d0',d.label));else marker(320,330,'#77c0d0','EXIT / E');sprite(p.x,p.y,p.dir,Math.floor(step)%4);if(p.z==='city'){ctx.strokeStyle='rgba(134,191,218,.22)';ctx.lineWidth=1;ctx.beginPath();rain.forEach(r=>{r.y=(r.y+dt*r.v)%360;r.x=(r.x-dt*20+640)%640;ctx.moveTo(r.x,r.y);ctx.lineTo(r.x-3,r.y+8)});ctx.stroke()}ctx.fillStyle='rgba(6,14,24,.82)';ctx.fillRect(10,10,160,29);ctx.fillStyle='#7fe9e5';ctx.font='10px monospace';ctx.textAlign='left';ctx.fillText('NEO MADRID / '+p.z.toUpperCase(),17,22);ctx.fillStyle='#d5e0ec';ctx.fillText(a?'TARGET '+MISSIONS[s.index].id+' / '+a.z.toUpperCase():'MISSION COMPLETE',17,33);if(a&&a.z===p.z&&Math.hypot(p.x-a.x,p.y-a.y)<38){ctx.fillStyle='#142a3b';ctx.fillRect(240,320,160,22);ctx.fillStyle='#ffe2a1';ctx.textAlign='center';ctx.fillText('PRESS E TO INTERACT',320,335)}requestAnimationFrame(frame)}
$('begin').onclick=()=>{started=true;$('start').hidden=true;C.focus();showHome()};$('focus').onclick=()=>C.focus();$('interact').onclick=interact;$('full').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();else $('screen').requestFullscreen?.()};$('reset').onclick=()=>{if(confirm('¿Iniciar nueva partida? Se eliminará el progreso local.')){s=fresh();save();p={x:475,y:345,dir:0,z:'city'};render();showHome()}};
$('export').onclick=()=>{let rows=['id,submision,estado,errores,intentos,nota',...MISSIONS.map(m=>{const r=s.states[m.id]||{};return [s.id,m.id,r.status||'new',r.errors||0,r.tries||0,r.grade??''].join(',')})];const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([rows.join('\n')],{type:'text/csv'}));a.download='progreso-'+s.id+'.csv';a.click();URL.revokeObjectURL(a.href)};
let audio=null,timer=null,beat=0;$('audio').onclick=async()=>{if(timer){clearInterval(timer);timer=null;audio.suspend();$('audio').textContent='Sonido: OFF';return}audio=audio||new AudioContext();await audio.resume();$('audio').textContent='Sonido: ON';timer=setInterval(()=>{let o=audio.createOscillator(),g=audio.createGain(),now=audio.currentTime;o.type=beat%4===0?'triangle':'sine';o.frequency.value=[110,110,164.81,130.81,98,98,146.83,123.47][beat++%8];g.gain.setValueAtTime(.0001,now);g.gain.exponentialRampToValueAtTime(.025,now+.03);g.gain.exponentialRampToValueAtTime(.0001,now+.22);o.connect(g);g.connect(audio.destination);o.start();o.stop(now+.23)},260)};
